<?php
$appPage='support';$appTitle='Support center';require __DIR__.'/../includes/customer_header.php';$notice='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();$action=$_POST['action']??'';if($action==='create'){$subject=trim($_POST['subject']??'');$body=trim($_POST['message']??'');$category=$_POST['category']??'';if(!in_array($category,['account','card','funding','transfer','credit','security','other'],true)||strlen($subject)<4||strlen($body)<10)throw new InvalidArgumentException('Complete the subject, category, and message.');$pdo->beginTransaction();$reference=Reference::generate('SUP');$pdo->prepare('INSERT INTO support_cases(reference,user_id,category,subject,priority) VALUES(?,?,?,?,?)')->execute([$reference,$customerId,$category,substr($subject,0,160),$category==='security'?'high':'normal']);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO support_messages(case_id,author_user_id,body) VALUES(?,?,?)')->execute([$id,$customerId,substr($body,0,5000)]);$pdo->commit();$notice='Support case '.$reference.' was created.';}elseif($action==='reply'){$id=(int)($_POST['case_id']??0);$body=trim($_POST['message']??'');if(strlen($body)<2)throw new InvalidArgumentException('Enter a reply.');$stmt=$pdo->prepare("SELECT 1 FROM support_cases WHERE case_id=? AND user_id=? AND status<>'closed'");$stmt->execute([$id,$customerId]);if(!$stmt->fetchColumn())throw new RuntimeException('Case is not available.');$pdo->prepare('INSERT INTO support_messages(case_id,author_user_id,body) VALUES(?,?,?)')->execute([$id,$customerId,substr($body,0,5000)]);$pdo->prepare("UPDATE support_cases SET status='open' WHERE case_id=?")->execute([$id]);$notice='Reply added.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}$selected=(int)($_GET['case']??0);$stmt=$pdo->prepare('SELECT * FROM support_cases WHERE user_id=? ORDER BY updated_at DESC');$stmt->execute([$customerId]);$cases=$stmt->fetchAll();$messages=[];if($selected){$stmt=$pdo->prepare('SELECT sm.body,sm.created_at,u.full_name,u.role FROM support_messages sm JOIN support_cases sc ON sc.case_id=sm.case_id JOIN users u ON u.user_id=sm.author_user_id WHERE sm.case_id=? AND sc.user_id=? AND sm.is_internal=0 ORDER BY sm.created_at');$stmt->execute([$selected,$customerId]);$messages=$stmt->fetchAll();}
?>
<?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><div class="app-grid"><section class="panel span-5"><h2>Start a support case</h2><p class="muted">Never send passwords, one-time codes, or complete card details.</p><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="action" value="create"><div class="field full"><label>Category</label><select name="category"><?php foreach(['account','card','funding','transfer','credit','security','other'] as $v):?><option><?=$v?></option><?php endforeach?></select></div><div class="field full"><label>Subject</label><input name="subject" maxlength="160" required></div><div class="field full"><label>How can we help?</label><textarea name="message" maxlength="5000" required></textarea></div><button class="button button-primary">Create case</button></form></section><section class="panel span-7"><h2>Your cases</h2><?php foreach($cases as $case):?><a href="support.php?case=<?=$case['case_id']?>" class="note" style="display:block;color:inherit"><strong><?=e($case['reference'])?> · <?=e($case['subject'])?></strong><br><span class="muted"><?=e(str_replace('_',' ',$case['status']))?> · updated <?=e(formatDate($case['updated_at']))?></span></a><?php endforeach;if(!$cases):?><div class="empty">You have no support cases.</div><?php endif?></section><?php if($selected):?><section class="panel span-12"><h2>Case conversation</h2><?php foreach($messages as $message):?><div class="note"><strong><?=e($message['role']==='customer'?'You':'Valtoria support')?></strong><small> · <?=e(formatDate($message['created_at']))?></small><p><?=nl2br(e($message['body']))?></p></div><?php endforeach?><form method="post" class="compact-form"><?=csrfField()?><input type="hidden" name="action" value="reply"><input type="hidden" name="case_id" value="<?=$selected?>"><input name="message" maxlength="5000" required placeholder="Add a reply"><button class="button button-primary">Send reply</button></form></section><?php endif?></div><?php require __DIR__.'/../includes/customer_footer.php';?>
